// Interoperability tests against the python-omemo reference stack
// (xeddsa / x3dh / doubleratchet / oldmemo / twomemo). Test vectors are
// generated by scripts/gen_vectors.py into vectors.json. A subset of tests
// call scripts/py_verify.py to let the reference stack verify or decrypt
// output produced by this implementation; those tests are skipped when the
// venv is not available.

import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { describe, expect, it } from 'vitest'

import { x25519 } from '@noble/curves/ed25519.js'

import {
  aes128GcmDecrypt,
  aes128GcmEncrypt,
  aes256CbcDecrypt,
  aes256CbcEncrypt
} from '../../src/crypto/aes'
import { hkdfSha256 } from '../../src/crypto/kdf'
import {
  curvePublicToEdPublic,
  curveSecretSignBit,
  decodeCurveKeyWire,
  edPublicToCurvePublic,
  edSecretToCurveSecret,
  encodeCurveKeyWire,
  x25519SharedSecret
} from '../../src/crypto/keys'
import { xed25519Sign, xed25519Verify } from '../../src/crypto/xed25519'
import { bytesToHex, hexToBytes } from '../../src/internal/bytes'
import { parseXml } from '../../src/internal/xml'
import {
  decodeAuthenticatedMessage,
  decodeKeyExchange,
  decodeOmemoMessage,
  encodeAuthenticatedMessage,
  encodeKeyExchange,
  encodeOmemoMessage
} from '../../src/protocol/messages'
import { PROFILES } from '../../src/protocol/profiles'
import { Session } from '../../src/protocol/session'
import type { SessionState } from '../../src/protocol/session'
import { sessionResponder } from '../../src/protocol/sessionInit'
import { x3dhInitiate, x3dhRespond } from '../../src/protocol/x3dh'
import type { ParsedBundle } from '../../src/protocol/bundle'
